export function redact(text: string): string {
  return text
    .replace(/\b(?:sk-[A-Za-z0-9_-]{12,}|gh[pousr]_[A-Za-z0-9_]{15,})\b/g, '[redacted]')
    .replace(/(Bearer\s+)[A-Za-z0-9._~-]{16,}/gi, '$1[redacted]')
    .replace(/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g, '[redacted]');
}
export async function readDocument(id: string): Promise<string | null> {
  if (!Object.hasOwn(DOCUMENTS, id)) return null;
  const path = DOCUMENTS[id].path;
  if ((await stat(path)).size > 256_000) throw new Error('Document exceeds the local preview limit.');
  return redact(await readFile(path, 'utf8'));
}
