let lastProbe = 0;
export async function probeTargets(force = false): Promise<void> {
  if (pending) return pending;
  if (!force && Date.now() - lastProbe < 60_000) return;
  pending = (async () => {
    health = await Promise.all(targets.map(async target => {
      const start = Date.now(); const checkedAt = new Date().toISOString();
      try {
        const response = await fetch(target.url, { signal: AbortSignal.timeout(6500), redirect: 'error', headers: { Accept: 'application/json' } });
        await response.body?.cancel();
        return { ...target, code: response.status, checkedAt, ms: Date.now() - start, status: response.ok ? 'up' : 'degraded' } as Health;
      } catch { return { ...target, checkedAt, ms: Date.now() - start, status: 'down', detail: 'No response within the bounded check.' } as Health; }
    }));
    lastProbe = Date.now();
  })();
  try { await pending; } finally { pending = null; }
}
export function summarizeTelemetry(input: string): { runs: Run[]; warnings: string[] } {
  const grouped = new Map<string, Run>(); const warnings: string[] = []; let malformed = 0; const lines = input.split('\n');
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].trim(); if (!line) continue;
    let event: Record<string, unknown>;
    try { event = JSON.parse(line); } catch { if (index < lines.length - 1) malformed++; continue; }
    if (typeof event.run_id !== 'string' || !/^[a-zA-Z0-9_-]{1,80}$/.test(event.run_id) || typeof event.ts !== 'number' || !Number.isFinite(event.ts)) { malformed++; continue; }
    const run = grouped.get(event.run_id) ?? { id: event.run_id, started: event.ts, ended: event.ts, events: 0, ms: 0, errors: 0, costUsd: 0, standIn: false, stages: [] };
    run.started = Math.min(run.started, event.ts); run.ended = Math.max(run.ended, event.ts); run.events++;
    if (event.ok === false || event.event === 'error') run.errors++;
    if (typeof event.cost_usd === 'number' && Number.isFinite(event.cost_usd) && event.cost_usd >= 0) run.costUsd += event.cost_usd;
    run.standIn ||= /stand.?in|fallback|local.?mode|local wave|local runner|draft.only/i.test(String(event.note ?? ''));
    if (typeof event.stage === 'string' && /^[a-zA-Z0-9_-]{1,40}$/.test(event.stage) && !run.stages.includes(event.stage)) run.stages.push(event.stage);
    run.ms = (run.ended - run.started) * 1000; grouped.set(run.id, run);
  }
  if (malformed) warnings.push(`${malformed} unreadable telemetry rows were skipped.`);
  return { runs: [...grouped.values()].sort((a, b) => b.started - a.started).slice(0, 12), warnings };
}
